recorded-motion.entry:
import { glyph, glyphCapabilities } from '@labpics/icons/ir';
import { compileSymbolEffect } from '@labpics/icons/motion';
console.log(compileSymbolEffect(glyph({ icon: 'time' }), glyphCapabilities('time'), 'time.advance', { duration: 400 }));

